    [9649]={name="Royal Highmark Vestments",quality=3,ilvl=55,sourceType="quest_reward",instructions="Reward from the quest 'Venom to the Undercity' - pick it over the other choices. In The Hinterlands.",zone="The Hinterlands",questName="Venom to the Undercity",lore="The venom you gathered from the Witherbark's spider god is quite a find! I've been able to kill nearly two dozen rabbits with just a drop of the stuff."},
