    [23046]={name="The Restrained Essence of Sapphiron",quality=4,ilvl=90,reqLevel=60,sourceType="boss_drop",instructions="Drops from Sapphiron.",npc="Sapphiron",lore="A blue dragon slain in Northrend and raised as a frost wyrm. He guards the final approach to Kel'Thuzad's chamber.",proc="Use: Increases damage and healing done by magical spells and effects by up to 130 for 20 sec. (2 Min Cooldown)"},
    [23057]={name="Gem of Trapped Innocents",quality=4,ilvl=92,reqLevel=60,sourceType="boss_drop",instructions="Drops from Kel'Thuzad in Naxxramas.",zone="Naxxramas",npc="Kel'Thuzad",lore="Once an archmage of the Kirin Tor, he left Dalaran to found the Cult of the Damned and served Ner'zhul willingly. Killed at Andorhal and raised as a lich, he rules Naxxramas from a phylactery at its heart."},
    [23125]={name="Chains of the Lich",quality=3,ilvl=60,reqLevel=55,sourceType="world_drop",instructions="Drops from Balzaphon (rare elite).",npc="Balzaphon"},
